// This file is automatically generated. Do not edit it directly.
// EXCEPTION: added a diagnostic client-side throw below when getSession()
// comes back with no token, instead of silently sending no Authorization
// header and letting the server report a generic "Unauthorized". If this
// file gets regenerated, the diagnostic (not the original logic) is lost;
// re-add it if this exact failure mode resurfaces.
import { createMiddleware } from "@tanstack/react-start";
import { supabase } from "./client";

// Must be registered as a global `functionMiddleware` in `src/start.ts`; otherwise
// the browser never attaches the bearer token to serverFn RPCs.
export const attachSupabaseAuth = createMiddleware({ type: "function" }).client(
  async ({ next }) => {
    const { data, error } = await supabase.auth.getSession();
    const token = data.session?.access_token;
    if (!token) {
      // Every prior theory for the server's "No authorization header
      // provided" assumed the token existed client-side and got lost in
      // transit. This proves or disproves that: if getSession() itself
      // has nothing to give, the problem is upstream of any network call
      // this app makes, in Supabase's own session state.
      const hasSession = !!data.session;
      const expiresAt = data.session?.expires_at;
      const now = Math.floor(Date.now() / 1000);
      throw new Error(
        `Not signed in (no access token). hasSession=${hasSession}` +
          (expiresAt ? ` expiresAt=${expiresAt} now=${now} expired=${expiresAt < now}` : "") +
          (error ? ` getSessionError=${error.message}` : ""),
      );
    }
    return next({
      headers: { Authorization: `Bearer ${token}` },
    });
  },
);
